// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, bytes32 h) internal {
        vm.assume(true);
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.setL1BlockValues(n, 1, 1, h, 1, h, 1, 1) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint64 n, bytes32 h) public {
        _run(n, h);
    }

    receive() external payable {}
}
